// Janela da semana atual (seg 00:00 → seg seguinte 00:00, exclusivo). `ref_date` (AAAA-MM-DD) permite simular outro dia.
const ZONE = $env.CHRONOS_TIMEZONE || 'America/Sao_Paulo'; // configurável no .env (CHRONOS_TIMEZONE)
const ref = String(($json && $json.ref_date) || '').slice(0, 10);
const refDt = /^\d{4}-\d{2}-\d{2}$/.test(ref) ? DateTime.fromISO(ref, { zone: ZONE }) : null;
const now = refDt && refDt.isValid ? refDt : $now.setZone(ZONE);
const start = now.startOf('week');
const end = start.plus({ weeks: 1 });
const last = end.minus({ days: 1 });
return [{ json: {
  start: start.toISO(), end: end.toISO(),
  start_date: start.toISODate(), last_date: last.toISODate(),
  label: start.toFormat('dd/MM') + ' – ' + last.toFormat('dd/MM'),
} }];

// Opcional: CHRONOS_CALENDARS="Agenda A;Agenda B" restringe as agendas consultadas; vazio = todas as que você pode editar.
const WANTED = String($env.CHRONOS_CALENDARS || '').split(';').map((s) => s.trim()).filter(Boolean);
const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s*(&|\be\b|\band\b)\s*/g, ' ').replace(/[^a-z0-9]/g, '');
const res = $json;
const fallback = (why) => [{ json: { calendar_id: 'primary', calendar_label: 'Agenda principal', list_error: why } }];
if (res.error || !Array.isArray(res.items)) {
  return fallback(res.error ? String(res.error.message || res.error).slice(0, 160) : 'resposta inesperada do calendarList');
}
const wanted = new Set(WANTED.map(norm));
const out = res.items
  .filter(c => !c.deleted && !c.hidden && (!wanted.size || wanted.has(norm(c.summaryOverride || c.summary)) || wanted.has(norm(c.summary))))
  .map(c => ({ json: { calendar_id: c.id, calendar_label: c.summaryOverride || c.summary, list_error: null } }));
return out.length ? out : fallback(wanted.size ? 'nenhuma das agendas de CHRONOS_CALENDARS encontrada no Google Calendar' : 'nenhuma agenda encontrada no Google Calendar');

const ZONE = $env.CHRONOS_TIMEZONE || 'America/Sao_Paulo'; // configurável no .env (CHRONOS_TIMEZONE)
const MAX = 3800; // teto por mensagem (o limite do Telegram é 4096)
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const per = $('Período').first().json;
const WD = ['', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado', 'Domingo'];
const WD3 = ['', 'seg', 'ter', 'qua', 'qui', 'sex', 'sáb', 'dom'];
const dm = (d) => d.toFormat('dd/MM');
const hm = (d) => d.toFormat('HH:mm');
const short = (d) => WD3[d.weekday] + ' ' + dm(d);
const dayStart = (d) => d.startOf('day');
const weekFirst = DateTime.fromISO(per.start_date, { zone: ZONE });
const weekLast = DateTime.fromISO(per.last_date, { zone: ZONE });

// Leitura dos eventos
let calError = null;
let calNote = null;
const entries = {}; // 'AAAA-MM-DD' → [{ order, key, title, text }]
let total = 0;
const sel = $('Selecionar agendas').all();
if (sel[0] && sel[0].json.list_error) calNote = sel[0].json.list_error;
const results = $input.all();
let okCalendars = 0;

function add(day, order, key, title, text) {
  const k = day.toISODate();
  (entries[k] = entries[k] || []).push({ order, key, title, text });
}

results.forEach((it, i) => {
  const r = it.json || {};
  const label = (sel[i] && sel[i].json.calendar_label) || r.summary || 'Agenda';
  if (r.error || !Array.isArray(r.items)) { calError = calError || String((r.error && (r.error.message || r.error)) || 'resposta inesperada').slice(0, 160); return; }
  okCalendars++;
  for (const e of r.items) {
    if (!e || e.status === 'cancelled' || !e.start) continue;
    if ((e.attendees || []).some((a) => a && a.self && a.responseStatus === 'declined')) continue;
    const allDay = !!e.start.date;
    let s;
    let en;
    let last;
    if (allDay) {
      s = DateTime.fromISO(e.start.date, { zone: ZONE });
      en = e.end && e.end.date ? DateTime.fromISO(e.end.date, { zone: ZONE }) : s.plus({ days: 1 });
      last = en.minus({ days: 1 }); // `end` de dia inteiro é exclusivo
      if (last < s) last = s;
    } else {
      s = DateTime.fromISO(e.start.dateTime).setZone(ZONE);
      en = e.end && e.end.dateTime ? DateTime.fromISO(e.end.dateTime).setZone(ZONE) : s;
      last = en > s ? en.minus({ milliseconds: 1 }) : s; // termina às 00:00 → não ocupa o dia seguinte
    }
    if (!s.isValid || !en.isValid) continue;
    const startDay = dayStart(s);
    const lastDay = dayStart(last);
    const from = startDay < weekFirst ? weekFirst : startDay;
    const to = lastDay > weekLast ? weekLast : lastDay;
    if (from > to) continue;

    const title = esc(e.summary || '(sem título)') + (e.recurringEventId ? ' 🔁' : '');
    const loc = e.location ? ' — ' + esc(String(e.location).replace(/\s+/g, ' ').trim().slice(0, 80)) : '';
    const cal = ' (' + esc(label) + ')';
    const multi = lastDay > startDay;
    const startsBefore = startDay < weekFirst;
    const endsAfter = lastDay > weekLast;
    const endTxt = allDay ? short(lastDay) : short(en) + ' ' + hm(en);
    total++;

    for (let d = from; d <= to; d = d.plus({ days: 1 })) {
      const isFirstVisible = d.toMillis() === from.toMillis();
      const isLastDay = d.toMillis() === lastDay.toMillis();
      if (!multi) {
        if (allDay) add(d, 0, s.toMillis(), title, '• Dia inteiro: ' + title + cal + loc);
        else add(d, 2, s.toMillis(), title, '• ' + (en > s ? hm(s) + '–' + hm(en) : hm(s)) + ' ' + title + cal + loc);
      } else if (isFirstVisible && !startsBefore) {
        add(d, allDay ? 0 : 2, s.toMillis(), title, '• ' + (allDay ? 'Dia inteiro: ' : hm(s) + ' ') + title + ' ▶ até ' + endTxt + cal + loc);
      } else if (isFirstVisible) {
        add(d, 1, 0, title, '↳ ' + title + ' (desde ' + short(startDay) + ', até ' + endTxt + ')');
      } else if (isLastDay) {
        add(d, 1, 0, title, '↳ ' + title + ' (termina' + (allDay ? '' : ' ' + hm(en)) + ')');
      } else if (d.toMillis() === weekLast.toMillis() && endsAfter) {
        add(d, 1, 0, title, '↳ ' + title + ' (continua até ' + endTxt + ')');
      } else {
        add(d, 1, 0, title, '↳ ' + title + ' (continua)');
      }
    }
  }
});

// Blocos por dia
const days = [];
for (let d = weekFirst; d <= weekLast; d = d.plus({ days: 1 })) {
  const list = (entries[d.toISODate()] || []).sort((a, b) => a.order - b.order || a.key - b.key || a.title.localeCompare(b.title));
  const head = '<b>' + WD[d.weekday] + ' ' + dm(d) + '</b>';
  days.push({ key: d.toISODate(), text: list.length ? head + '\n' + list.map((x) => x.text).join('\n') : head + ' — livre' });
}

const footer = [];
if (calError && okCalendars === 0) footer.push('<i>Google Calendar indisponível: ' + esc(calError) + '</i>');
else if (calError) footer.push('<i>Uma das agendas não respondeu: ' + esc(calError) + '</i>');
if (calNote) footer.push('<i>(só a agenda principal — ' + esc(calNote) + ')</i>');
const footerText = footer.length ? '\n\n' + footer.join('\n') : '';

const header = '📅 <b>Sua semana</b> (' + per.label + ')';
let body = days.map((d) => d.text).join('\n\n');
let emptyWeek = false;
if (okCalendars === 0) {
  body = '';
  days.length = 0;
} else if (total === 0) {
  emptyWeek = true;
  body = 'Nenhum compromisso nesta semana. 🎉';
  days.length = 0;
}
const full = header + '\n\n' + body + footerText;
const needsSplit = !emptyWeek && okCalendars > 0 && full.length > MAX;

const system = 'Você divide uma agenda semanal em mensagens do Telegram. Responda APENAS JSON: {"blocks":[{"first_day":"AAAA-MM-DD"}, ...]}, onde cada item é o primeiro dia de uma mensagem, em ordem. O primeiro bloco começa no primeiro dia da lista. Regras: nunca divida no meio de um dia; use o menor número de mensagens possível; equilibre o tamanho entre elas; cada mensagem (soma dos caracteres dos dias + 2 por separador entre dias + ~60 de cabeçalho' + (footerText ? ' + ' + footerText.length + ' de rodapé na última' : '') + ') deve ter no máximo ' + MAX + ' caracteres. Use somente chaves de dia que existem na lista. Não reescreva nem resuma o texto.';
const user = 'Dias (chave | caracteres):\n' + days.map((d) => d.key + ' | ' + d.text.length).join('\n') + '\n\nTexto completo:\n' + body;

return [{ json: {
  chat_id: $env.TELEGRAM_CHAT_ID, label: per.label, header, body, footer: footerText, days, max: MAX,
  empty_week: emptyWeek, needs_split: needsSplit, total_events: total, ok_calendars: okCalendars, system, user,
} }];

// Monta as mensagens a partir dos dias. O DeepSeek só sugere onde cortar; o código monta e valida.
const m = $('Montar agenda').first().json;
const MAX = m.max;
const out = (texts) => texts.map((text) => ({ json: { chat_id: m.chat_id, text } }));

if (!m.days.length) return out([m.header + '\n\n' + m.body + m.footer]);

// Dia maior que o teto (improvável): único caso em que se quebra por linha, sem perder conteúdo.
const hdrMax = '📅 <b>Sua semana (99/99)</b> · ' + m.label + '\n\n';
const room = MAX - hdrMax.length - m.footer.length;
const units = [];
for (const d of m.days) {
  if (d.text.length <= room) { units.push(d); continue; }
  const lines = d.text.split('\n');
  const title = lines[0];
  let cur = title;
  for (const line of lines.slice(1)) {
    if (cur.length + 1 + line.length > room) { units.push({ key: d.key, text: cur }); cur = title.replace('</b>', '</b> (cont.)') + '\n' + line; } else cur += '\n' + line;
  }
  units.push({ key: d.key, text: cur });
}

const bodyOf = (g) => g.map((u) => u.text).join('\n\n');
const headerOf = (i, n) => (n === 1 ? m.header : '📅 <b>Sua semana (' + (i + 1) + '/' + n + ')</b> · ' + m.label);
const build = (groups) => groups.map((g, i) => headerOf(i, groups.length) + '\n\n' + bodyOf(g) + (i === groups.length - 1 ? m.footer : ''));
const original = bodyOf(units);
const valid = (groups) => groups.length > 0
  && groups.every((g) => g.length > 0)
  && groups.map(bodyOf).join('\n\n') === original
  && build(groups).every((t) => t.length <= MAX);

// Divisão determinística: encaixa dias em sequência enquanto couber.
function greedy() {
  const groups = [];
  let cur = [];
  for (const u of units) {
    const fits = build([...groups, [...cur, u]]).every((t) => t.length <= MAX);
    if (cur.length && !fits) { groups.push(cur); cur = [u]; } else cur.push(u);
  }
  if (cur.length) groups.push(cur);
  return groups;
}

let groups = null;
if (m.needs_split) {
  try {
    const raw = $('DeepSeek: onde dividir').first().json.choices[0].message.content;
    const firsts = (JSON.parse(raw).blocks || []).map((b) => b && b.first_day);
    const idx = firsts.map((k) => units.findIndex((u) => u.key === k));
    const ok = idx.length > 0 && idx[0] === 0 && idx.every((v, i) => v >= 0 && (i === 0 || v > idx[i - 1]));
    if (ok) {
      const cand = idx.map((start, i) => units.slice(start, i + 1 < idx.length ? idx[i + 1] : units.length));
      if (valid(cand)) groups = cand;
    }
  } catch (e) { groups = null; }
}
if (!groups) {
  groups = greedy();
  if (!valid(groups)) groups = units.map((u) => [u]); // último recurso: um dia por mensagem
}
return out(build(groups));
